const locales = ["en", "fr", "de", "es", "it", "ja", "ko", "pt", "ru", "zh"];

// gt-next resolves entries by content hash, so load the hash-keyed catalogs
// generated by `gt` (public/_gt), one chunk per locale.
export default async function loadTranslations(locale: string) {
  const safeLocale = locales.includes(locale) ? locale : "en";
  const module = await import(`./public/_gt/${safeLocale}.json`);
  return module.default;
}
